from math import ceil, log

def getMid(s, e):
	return s + (e - s) // 2

def MaxUtil(st, ss, se, l, r, node):
	if l <= ss and r >= se:
		return st[node]
	if se < l or ss > r:
		return [-1, -1]
	mid = getMid(ss, se)
	a = MaxUtil(st, ss, mid, l, r, 2 * node + 1)
	b = MaxUtil(st, mid + 1, se, l, r, 2 * node + 2)
	if a[0] < b[0]:
		res = b
	else:
		res = a
	return res

def getMax(st, n, l, r):
	return MaxUtil(st, 0, n - 1, l, r, 0)

def constructSTUtil(arr, ss, se, st, si):
	if ss == se:
		st[si] = [arr[ss], ss]
		return [arr[ss], ss]
	mid = getMid(ss, se)
	a = constructSTUtil(arr, ss, mid, st, si * 2 + 1)
	b = constructSTUtil(arr, mid + 1, se, st, si * 2 + 2)
	if a[0] < b[0]:
		st[si] = b
	else:
		st[si] = a
	return st[si]

def constructST(arr, n):
	x = ceil(log(n, 2))
	max_size = 2 * pow(2, x) - 1
	st = [[-1, -1]] * max_size
	constructSTUtil(arr, 0, n - 1, st, 0)
	return st

def next(arr, n):
	s = []
	arr1 = [-1 for i in range(n)]
	for i in range(n - 1, -1, -1):
		while len(s) > 0 and arr[s[-1]] <= arr[i]:
			s.pop()
		if len(s) != 0:
			arr1[i] = s[-1]
		s.append(i)
	return arr1

def lenend(right, n):
	dic = [0] * n
	arr = [0] * n
	for i in range(n):
		arr[i] = dic[i] + 1
		if dic[right[i]] < arr[i] and right[i] != -1:
			dic[right[i]] = arr[i]
	return arr

def lenstart(right, n):
	dic = [0] * n
	arr = [0] * n
	for i in range(n - 1, -1, -1):
		if right[i] != -1:
			arr[i] = dic[right[i]] + 1
		else:
			arr[i] = 1
		if dic[i] < arr[i]:
			dic[i] = arr[i]
	return arr
